struct AddressBallast {
 std::vector<void*> blocks;
 ~AddressBallast(){for(void* p:blocks)assert(VirtualFree(p,0,MEM_RELEASE));}
 uint64_t available()const{MEMORYSTATUSEX m{};m.dwLength=sizeof m;assert(GlobalMemoryStatusEx(&m));return m.ullAvailVirtual;}
 uint64_t largest()const{MEMORY_BASIC_INFORMATION m{};uintptr_t p=0;uint64_t best=0;while(VirtualQuery(reinterpret_cast<void*>(p),&m,sizeof m)){if(m.State==MEM_FREE)best=std::max<uint64_t>(best,m.RegionSize);uintptr_t end=reinterpret_cast<uintptr_t>(m.BaseAddress)+m.RegionSize;if(end<=p)break;p=end;}return best;}
 void fill(unsigned mib){const uint64_t target=(uint64_t(mib)<<20)+4*1024*1024;while(available()>target+65536){size_t n=size_t(std::min<uint64_t>(16ull<<20,(available()-target)&~65535ull));void* p=VirtualAlloc(nullptr,n,MEM_RESERVE,PAGE_NOACCESS);assert(p);blocks.push_back(p);}
  // Split large free spans using only allocation-granularity reservations.
  // Aggregate free space remains above the requested entry floor throughout.
  for(unsigned pass=0;pass<256&&largest()>(96ull<<20);++pass){MEMORY_BASIC_INFORMATION m{};uintptr_t p=0;bool split=false;while(VirtualQuery(reinterpret_cast<void*>(p),&m,sizeof m)){uintptr_t end=reinterpret_cast<uintptr_t>(m.BaseAddress)+m.RegionSize;if(m.State==MEM_FREE&&m.RegionSize>(96u<<20)){uintptr_t mid=(reinterpret_cast<uintptr_t>(m.BaseAddress)+m.RegionSize/2+65535)&~uintptr_t(65535);void* q=VirtualAlloc(reinterpret_cast<void*>(mid),65536,MEM_RESERVE,PAGE_NOACCESS);if(q){blocks.push_back(q);split=true;break;}}if(end<=p)break;p=end;}if(!split)break;}
  while(available()>(uint64_t(mib)<<20)+384*1024){void* p=VirtualAlloc(nullptr,65536,MEM_RESERVE,PAGE_NOACCESS);assert(p);blocks.push_back(p);}
  assert(available()>=(uint64_t(mib)<<20)&&largest()<=(96ull<<20)&&largest()>=(33ull<<20));
 }
};
struct VaSampler {
 std::atomic<bool> stop{false},enabled{false};std::atomic<uint64_t> minimum{UINT64_MAX},samples{0};std::thread thread;
 VaSampler():thread([this]{while(!stop.load()){if(enabled.load()){MEMORYSTATUSEX m{};m.dwLength=sizeof m;if(GlobalMemoryStatusEx(&m)){auto old=minimum.load();while(m.ullAvailVirtual<old&&!minimum.compare_exchange_weak(old,m.ullAvailVirtual)){}++samples;}}Sleep(1);}}){}
 ~VaSampler(){stop.store(true);thread.join();}
 void begin(){minimum.store(UINT64_MAX);samples.store(0);enabled.store(true);}void end(){enabled.store(false);}
};
